package com.fixflow.mall.api;

import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.service.OrderService;
import com.fixflow.mall.service.UserService;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
public class MallControllerTest {

    @Mock
    private UserService userService;

    @Mock
    private OrderService orderService;

    @InjectMocks
    private MallController mallController;

    @Test
    @DisplayName("测试 getOrder 方法在正常输入下返回正确的订单")
    void testGetOrderWithValidId() {
        Long orderId = 1L;
        MallOrder expectedOrder = mock(MallOrder.class);

        when(orderService.findOrder(orderId)).thenReturn(expectedOrder);

        MallOrder result = mallController.getOrder(orderId);

        assertNotNull(result);
        assertEquals(expectedOrder, result);
        verify(orderService).findOrder(orderId);
    }

    @Test
    @DisplayName("测试 getOrder 方法修复后，在原来导致异常的输入下不再抛出异常")
    void testGetOrderWithPreviouslyBrokenInput() {
        Long orderId = 123L;
        MallOrder mockOrder = mock(MallOrder.class);
        when(orderService.findOrder(orderId)).thenReturn(mockOrder);

        assertDoesNotThrow(() -> mallController.getOrder(orderId));

        MallOrder result = mallController.getOrder(orderId);
        assertEquals(mockOrder, result);
    }

    @Test
    @DisplayName("测试 getOrder 方法处理空值 orderId 的情况")
    void testGetOrderWithNullId() {
        Long orderId = null;
        when(orderService.findOrder(orderId)).thenReturn(null);

        MallOrder result = mallController.getOrder(orderId);

        assertNull(result);
        verify(orderService).findOrder(orderId);
    }
}
